UPDATE "City" SET "published" = 1 WHERE "slug" IN ('oklahoma-city', 'salt-lake-city', 'las-vegas', 'sacramento');
UPDATE "City" SET "intro" = 'Oklahoma City''s listings center on Mahj & Bougie, which runs social play and beginner lessons at venues around the city, including a lakeside restaurant and a downtown bar. Events tend to include food or drinks and carry a ticket price, so check the event details first. If you are new, the lesson nights are the natural place to start, and social play afterwards is a relaxed way to practice with the National Mah Jongg League card.' WHERE "slug" = 'oklahoma-city';
UPDATE "City" SET "intro" = 'Salt Lake City''s listings center on the Jewish Community Center, whose Learn to Play Mahjong course teaches American Mahjong with the National Mah Jongg League card. It runs as a six-week series with a daytime session and an evening session, and pricing differs for members and the public. It is a good fit if you want a structured introduction. Contact the JCC to ask about what comes after the course.' WHERE "slug" = 'salt-lake-city';
UPDATE "City" SET "intro" = 'Las Vegas has a dedicated American Mahjong studio on West Sahara Avenue. Las Vegas Mahjong offers a series of lessons, Mahj 101, 102 and 103, along with weekday social open play, and it references the National Mah Jongg League card on its own site. New players can start with Mahj 101 and move up through the series, then join open play. Check the schedule page for current times and pricing before you visit.' WHERE "slug" = 'las-vegas';
UPDATE "City" SET "intro" = 'Sacramento''s listings center on the Learnery at Sierra 2 Center, where Sheri Graciano teaches American Mah Jongg classes. The Introduction class is for beginners and a second-level 2.0 class covers National Mah Jongg League rules in more depth. Classes are held in the evening and on weekday afternoons, and prices are modest. Check the Learnery calendar for dates and registration, since new sessions are added through the year.' WHERE "slug" = 'sacramento';
